#include <locale>
#include <iomanip>
#include <iostream>
#include <string>
int main() {
    std::locale loc("en_US.UTF-8");  // Create a locale object, which aggregates facets like moneypunct.
    std::cout.imbue(loc);  // Imbue the stream with the locale, triggering runtime use of facets.
    double amount = 1234.56;  // Example monetary value.
    std::cout << std::showbase << std::put_money(static_cast<long double>(amount)) << std::endl;  // Uses money_put facet, which calls moneypunct virtual functions.
    return 0;
}
